=== FILE: apb_regs.v ===
// apb_regs: four 32-bit read/write registers behind an APB4 subordinate port.
// Implements interface_spec.md and microarchitecture.md (task prj-05388a2c24).
// Zero wait states: pready is tied high; the only state is the four registers.
module apb_regs #(
  parameter ADDR_WIDTH = 8,
  parameter DATA_WIDTH = 32
) (
  input  wire                    pclk,
  input  wire                    presetn,
  input  wire [ADDR_WIDTH-1:0]   paddr,
  input  wire                    psel,
  input  wire                    penable,
  input  wire                    pwrite,
  input  wire [DATA_WIDTH-1:0]   pwdata,
  input  wire [DATA_WIDTH/8-1:0] pstrb,
  output wire [DATA_WIDTH-1:0]   prdata,
  output wire                    pready,
  output wire                    pslverr
);

  localparam STRB_WIDTH = DATA_WIDTH / 8;

  // Register file: four separate flops.
  reg [DATA_WIDTH-1:0] reg0;
  reg [DATA_WIDTH-1:0] reg1;
  reg [DATA_WIDTH-1:0] reg2;
  reg [DATA_WIDTH-1:0] reg3;

  // merge(old, data, strb): copy each byte of data whose strobe is set,
  // keep the other bytes of old.
  function [DATA_WIDTH-1:0] merge;
    input [DATA_WIDTH-1:0] old_v;
    input [DATA_WIDTH-1:0] data;
    input [STRB_WIDTH-1:0] strb;
    integer i;
    begin
      merge = old_v;
      for (i = 0; i < STRB_WIDTH; i = i + 1) begin
        if (strb[i]) begin
          merge[8*i +: 8] = data[8*i +: 8];
        end
      end
    end
  endfunction

  // Access phase: the one cycle in which the response is sampled and a
  // write takes effect.
  wire access = psel && penable;

  // Decode: word aligned and inside 0x0..0xC.
  wire mapped = (paddr[1:0] == 2'b00) &&
                (paddr[ADDR_WIDTH-1:4] == {(ADDR_WIDTH-4){1'b0}});

  wire [1:0] idx   = paddr[3:2];
  wire       wr_en = access && pwrite && mapped;
  wire       rd_en = access && !pwrite && mapped;

  // 4:1 multiplexer of the registers.
  reg [DATA_WIDTH-1:0] cur_reg;
  always @(*) begin
    case (idx)
      2'd0:    cur_reg = reg0;
      2'd1:    cur_reg = reg1;
      2'd2:    cur_reg = reg2;
      default: cur_reg = reg3;
    endcase
  end

  wire [DATA_WIDTH-1:0] wr_value = merge(cur_reg, pwdata, pstrb);

  // Synchronous, active-low reset; write on the edge that ends the access phase.
  always @(posedge pclk) begin
    if (!presetn) begin
      reg0 <= {DATA_WIDTH{1'b0}};
      reg1 <= {DATA_WIDTH{1'b0}};
      reg2 <= {DATA_WIDTH{1'b0}};
      reg3 <= {DATA_WIDTH{1'b0}};
    end else if (wr_en) begin
      case (idx)
        2'd0:    reg0 <= wr_value;
        2'd1:    reg1 <= wr_value;
        2'd2:    reg2 <= wr_value;
        default: reg3 <= wr_value;
      endcase
    end
  end

  assign prdata  = rd_en ? cur_reg : {DATA_WIDTH{1'b0}};
  assign pready  = 1'b1;
  assign pslverr = access && !mapped;

`ifdef FORMAL
  // ------------------------------------------------------------------
  // Design-intent properties (microarchitecture.md section 6).
  // ------------------------------------------------------------------
  reg f_past_valid;
  initial f_past_valid = 1'b0;
  always @(posedge pclk) f_past_valid <= 1'b1;

  // Independent decode and register view.
  wire f_access = psel && penable;
  wire f_mapped = (paddr == 'h0) || (paddr == 'h4) ||
                  (paddr == 'h8) || (paddr == 'hC);
  wire [4*DATA_WIDTH-1:0] f_regs = {reg3, reg2, reg1, reg0};
  wire [DATA_WIDTH-1:0]   f_addressed = f_regs[paddr[3:2]*DATA_WIDTH +: DATA_WIDTH];

  // Manager assumptions.
  always @(*) begin
    if (!f_past_valid) assume(!presetn);
    if (!presetn)      assume(!psel);
    if (penable)       assume(psel);
  end

  always @(posedge pclk) begin
    if (f_past_valid) begin
      // penable only in the cycle after a setup phase
      if (penable)
        assume($past(psel) && !$past(penable));
      // a setup phase is followed by its access phase, request held stable
      if ($past(psel) && !$past(penable) && presetn)
        assume(psel && penable &&
               (paddr  == $past(paddr))  && (pwrite == $past(pwrite)) &&
               (pwdata == $past(pwdata)) && (pstrb  == $past(pstrb)));
    end
  end

  // Response rules.
  always @(*) begin
    assert(pready);
    if (!f_access) begin
      assert(prdata == {DATA_WIDTH{1'b0}});
      assert(!pslverr);
    end else begin
      assert(pslverr == !f_mapped);
      if (!pwrite && f_mapped)
        assert(prdata == f_addressed);
      else
        assert(prdata == {DATA_WIDTH{1'b0}});
    end
  end

  // Registers are zero after reset.
  always @(posedge pclk) begin
    if (f_past_valid && !$past(presetn))
      assert(f_regs == {(4*DATA_WIDTH){1'b0}});
  end

  // Each byte changes only in a mapped write access to its register with
  // its strobe set, and then to the written byte.
  genvar gi, gb;
  generate
    for (gi = 0; gi < 4; gi = gi + 1) begin : g_freg
      for (gb = 0; gb < STRB_WIDTH; gb = gb + 1) begin : g_fbyte
        always @(posedge pclk) begin
          if (f_past_valid && $past(presetn)) begin
            if ($past(f_access && pwrite && f_mapped &&
                      (paddr[3:2] == gi) && pstrb[gb]))
              assert(f_regs[DATA_WIDTH*gi + 8*gb +: 8] == $past(pwdata[8*gb +: 8]));
            else
              assert(f_regs[DATA_WIDTH*gi + 8*gb +: 8] ==
                     $past(f_regs[DATA_WIDTH*gi + 8*gb +: 8]));
          end
        end
      end
    end
  endgenerate

  // Covers: each register written and read back, partial strobes, errors.
  always @(posedge pclk) begin
    if (f_past_valid && presetn) begin
      cover(f_access && !pwrite && f_mapped && (paddr[3:2] == 2'd0) && (prdata == 32'h12345678));
      cover(f_access && !pwrite && f_mapped && (paddr[3:2] == 2'd1) && (prdata == 32'h9ABCDEF0));
      cover(f_access && !pwrite && f_mapped && (paddr[3:2] == 2'd2) && (prdata == 32'h0F1E2D3C));
      cover(f_access && !pwrite && f_mapped && (paddr[3:2] == 2'd3) && (prdata == 32'hDEADBEEF));
      cover(f_access && !pwrite && f_mapped && (paddr[3:2] == 2'd1) && (prdata == 32'h00AB00CD));
      cover(f_access && pwrite && pslverr);
      cover(f_access && !pwrite && pslverr);
    end
  end
`endif

endmodule
=== END FILE ===
