// apb_regs_tb: directed self-checking testbench for apb_regs.
// Inputs are driven after the falling edge; outputs are sampled 2 time
// units later, before the rising edge.
module apb_regs_tb;

  reg         pclk;
  reg         presetn;
  reg  [7:0]  paddr;
  reg         psel;
  reg         penable;
  reg         pwrite;
  reg  [31:0] pwdata;
  reg  [3:0]  pstrb;
  wire [31:0] prdata;
  wire        pready;
  wire        pslverr;

  apb_regs #(.ADDR_WIDTH(8), .DATA_WIDTH(32)) dut (
    .pclk    (pclk),
    .presetn (presetn),
    .paddr   (paddr),
    .psel    (psel),
    .penable (penable),
    .pwrite  (pwrite),
    .pwdata  (pwdata),
    .pstrb   (pstrb),
    .prdata  (prdata),
    .pready  (pready),
    .pslverr (pslverr)
  );

  reg [31:0]     model [0:3];
  integer        passed;
  integer        failed;
  integer        phase;
  integer        s;
  reg [31:0]     wd;
  reg [8*64-1:0] nonce;

  initial pclk = 1'b0;
  always #5 pclk = ~pclk;

  // Expected decode, written independently of the RTL.
  function tb_mapped;
    input [7:0] a;
    begin
      tb_mapped = (a == 8'h00) || (a == 8'h04) || (a == 8'h08) || (a == 8'h0C);
    end
  endfunction

  function [31:0] strb_mask;
    input [3:0] st;
    begin
      strb_mask = {{8{st[3]}}, {8{st[2]}}, {8{st[1]}}, {8{st[0]}}};
    end
  endfunction

  task check32;
    input [31:0] got;
    input [31:0] exp;
    input integer id;
    begin
      if (got === exp) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("check %0d (phase %0d, paddr 0x%02h): got 0x%08h expected 0x%08h",
               id, phase, paddr, got, exp);
      end
    end
  endtask

  task check1;
    input got;
    input exp;
    input integer id;
    begin
      if (got === exp) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("check %0d (phase %0d, paddr 0x%02h): got %b expected %b",
               id, phase, paddr, got, exp);
      end
    end
  endtask

  // One idle cycle: responses must be quiet.
  task idle;
    begin
      @(negedge pclk);
      psel    = 1'b0;
      penable = 1'b0;
      pwrite  = 1'b0;
      pstrb   = 4'h0;
      #2;
      check32(prdata, 32'h0, 1);
      check1(pslverr, 1'b0, 2);
    end
  endtask

  // Setup phase: responses must be quiet.
  task setup_phase;
    input        wr;
    input [7:0]  a;
    input [31:0] d;
    input [3:0]  st;
    begin
      @(negedge pclk);
      psel    = 1'b1;
      penable = 1'b0;
      pwrite  = wr;
      paddr   = a;
      pwdata  = d;
      pstrb   = st;
      #2;
      check32(prdata, 32'h0, 10);
      check1(pslverr, 1'b0, 11);
    end
  endtask

  task apb_write;
    input [7:0]  a;
    input [31:0] d;
    input [3:0]  st;
    reg          m;
    begin
      m = tb_mapped(a);
      setup_phase(1'b1, a, d, st);
      @(negedge pclk);
      penable = 1'b1;
      #2;
      check1(pready, 1'b1, 20);
      check1(pslverr, ~m, 21);
      check32(prdata, 32'h0, 22);
      if (m)
        model[a[3:2]] = (model[a[3:2]] & ~strb_mask(st)) | (d & strb_mask(st));
    end
  endtask

  task apb_read;
    input [7:0] a;
    reg         m;
    reg [31:0]  exp;
    begin
      m   = tb_mapped(a);
      exp = m ? model[a[3:2]] : 32'h0;
      setup_phase(1'b0, a, 32'hBAD0BAD0, 4'h0);
      @(negedge pclk);
      penable = 1'b1;
      #2;
      check1(pready, 1'b1, 30);
      check1(pslverr, ~m, 31);
      check32(prdata, exp, 32);
    end
  endtask

  task read_all;
    begin
      apb_read(8'h00);
      apb_read(8'h04);
      apb_read(8'h08);
      apb_read(8'h0C);
    end
  endtask

  task do_reset;
    input integer cycles;
    integer k;
    begin
      @(negedge pclk);
      presetn = 1'b0;
      psel    = 1'b0;
      penable = 1'b0;
      pwrite  = 1'b0;
      pstrb   = 4'h0;
      for (k = 0; k < cycles; k = k + 1)
        idle;
      model[0] = 32'h0;
      model[1] = 32'h0;
      model[2] = 32'h0;
      model[3] = 32'h0;
      @(negedge pclk);
      presetn = 1'b1;
      #2;
      check32(prdata, 32'h0, 3);
      check1(pslverr, 1'b0, 4);
    end
  endtask

  // Unmapped write must error and leave every register unchanged; unmapped
  // read must return zero with an error.
  task unmapped_pair;
    input [7:0] a;
    input [3:0] st;
    begin
      apb_write(a, 32'hDEADBEEF, st);
      apb_read(a);
    end
  endtask

  initial begin
    passed   = 0;
    failed   = 0;
    phase    = 0;
    nonce    = {8*64{1'b0}};
    presetn  = 1'b0;
    psel     = 1'b0;
    penable  = 1'b0;
    pwrite   = 1'b0;
    paddr    = 8'h00;
    pwdata   = 32'h0;
    pstrb    = 4'h0;
    wd       = 32'h0;
    model[0] = 32'h0;
    model[1] = 32'h0;
    model[2] = 32'h0;
    model[3] = 32'h0;
    if (!$value$plusargs("nirmaan_nonce=%s", nonce))
      nonce = {8*64{1'b0}};

    // Phase 1: reset, quiet outputs during reset.
    phase = 1;
    do_reset(3);

    // Phase 2: reset values, with an idle gap.
    phase = 2;
    apb_read(8'h00);
    idle;
    apb_read(8'h04);
    apb_read(8'h08);
    apb_read(8'h0C);

    // Phase 3: write then read every register, idle gaps between.
    phase = 3;
    apb_write(8'h00, 32'h11223344, 4'hF);
    idle;
    apb_read(8'h00);
    idle;
    apb_write(8'h04, 32'h55667788, 4'hF);
    idle;
    idle;
    apb_read(8'h04);
    apb_write(8'h08, 32'h99AABBCC, 4'hF);
    idle;
    apb_read(8'h08);
    apb_write(8'h0C, 32'hDDEEFF00, 4'hF);
    idle;
    apb_read(8'h0C);
    read_all;

    // Phase 4: back-to-back transfers, no idle cycles.
    phase = 4;
    apb_write(8'h04, 32'hCAFEF00D, 4'hF);
    apb_write(8'h08, 32'h0BADC0DE, 4'hF);
    apb_read(8'h04);
    apb_read(8'h08);
    apb_write(8'h0C, 32'h76543210, 4'hF);
    apb_read(8'h0C);
    apb_write(8'h00, 32'hFEDCBA98, 4'hF);
    apb_read(8'h00);
    apb_read(8'h00);
    read_all;

    // Phase 5: every strobe pattern on REG2, including none.
    phase = 5;
    apb_write(8'h08, 32'h00000000, 4'hF);
    apb_read(8'h08);
    for (s = 0; s < 16; s = s + 1) begin
      wd = {8'h10 + s[7:0], 8'h20 + s[7:0], 8'h30 + s[7:0], 8'h40 + s[7:0]};
      apb_write(8'h08, wd, s[3:0]);
      apb_read(8'h08);
    end
    for (s = 0; s < 16; s = s + 1) begin
      wd = ~{8'h50 + s[7:0], 8'h60 + s[7:0], 8'h70 + s[7:0], 8'h80 + s[7:0]};
      apb_write(8'h08, wd, s[3:0]);
      idle;
      apb_read(8'h08);
    end
    apb_write(8'h00, 32'hAAAAAAAA, 4'b0101);
    apb_read(8'h00);
    apb_write(8'h04, 32'h12345678, 4'b1000);
    apb_read(8'h04);
    apb_write(8'h0C, 32'h87654321, 4'b0000);
    apb_read(8'h0C);
    read_all;

    // Phase 6: PSLVERR policy, misaligned and out-of-range addresses.
    phase = 6;
    unmapped_pair(8'h01, 4'hF);
    unmapped_pair(8'h02, 4'hF);
    unmapped_pair(8'h03, 4'hF);
    unmapped_pair(8'h05, 4'hF);
    unmapped_pair(8'h0E, 4'hF);
    unmapped_pair(8'h0F, 4'hF);
    unmapped_pair(8'h10, 4'hF);
    unmapped_pair(8'h14, 4'hF);
    unmapped_pair(8'h1C, 4'hF);
    unmapped_pair(8'h40, 4'hF);
    unmapped_pair(8'h80, 4'hF);
    unmapped_pair(8'hFC, 4'hF);
    unmapped_pair(8'hFF, 4'hF);
    unmapped_pair(8'h10, 4'h0);
    unmapped_pair(8'h09, 4'b0011);
    read_all;

    // Phase 7: error transfers back to back with good ones.
    phase = 7;
    apb_write(8'h20, 32'h01010101, 4'hF);
    apb_write(8'h04, 32'h02020202, 4'hF);
    apb_read(8'h24);
    apb_read(8'h04);
    apb_write(8'h0D, 32'h03030303, 4'hF);
    apb_read(8'h0C);
    read_all;

    // Phase 8: reset again, then registers are zero.
    phase = 8;
    idle;
    do_reset(2);
    read_all;

    // Phase 9: writes work after the second reset.
    phase = 9;
    apb_write(8'h0C, 32'hA5A55A5A, 4'hF);
    apb_write(8'h00, 32'h5A5AA5A5, 4'b0110);
    read_all;
    idle;

    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end

  // Watchdog: a hang is a failed run.
  initial begin
    #1000000;
    $error("watchdog timeout");
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed + 1);
    $finish;
  end

endmodule
=== END FILE ===
